from django.views import View
from django.http import FileResponse, HttpResponseForbidden, Http404
from django.core.signing import TimestampSigner, BadSignature, SignatureExpired
from .models import AsyncExportJob

class ExportDownloadView(View):
    def get(self, request):
        if not request.user.is_authenticated:
            return HttpResponseForbidden("Authentication required")

        signature = request.GET.get('sig')
        if not signature:
            return HttpResponseForbidden("Missing signature")

        signer = TimestampSigner(salt='export-job-delivery')
        try:
            payload = signer.unsign_object(signature, max_age=3600)
            job_id = payload['export_job_id']
        except (BadSignature, SignatureExpired, KeyError):
            return HttpResponseForbidden("Signature verification failed")

        try:
            # Enforce that the job belongs to the requesting user and their tenant
            job = AsyncExportJob.objects.get(id=job_id, creator=request.user)
        except AsyncExportJob.DoesNotExist:
            raise Http404("Export not found")

        return FileResponse(job.output_file.open('rb'), as_attachment=True, filename=job.filename)
